#include <iostream>
#include <stdexcept>
#include <cstddef>

class SimpleArray {
private:
    std::size_t size;
    int* ptr;

public:
    explicit SimpleArray(int arraySize = 5) 
        : size(arraySize > 0 ? static_cast<std::size_t>(arraySize) 
                             : throw std::invalid_argument("Size must be > 0")),
          ptr(new int[size]) {
        for (std::size_t i = 0; i < size; ++i) {
            ptr[i] = 0;
        }
    }

    // Deep copy constructor
    SimpleArray(const SimpleArray& other) 
        : size(other.size), ptr(new int[other.size]) {
        for (std::size_t i = 0; i < size; ++i) {
            ptr[i] = other.ptr[i];
        }
    }

    ~SimpleArray() {
        delete[] ptr;
    }

    std::size_t getSize() const noexcept {
        return size;
    }

    void set(std::size_t index, int val) {
        if (index < size) ptr[index] = val;
    }

    int get(std::size_t index) const {
        return ptr[index];
    }
};

int main() {
    SimpleArray a1(3);
    a1.set(0, 10);
    a1.set(1, 20);
    a1.set(2, 30);

    SimpleArray a2 = a1; // Invokes copy constructor
    a2.set(1, 99);

    std::cout << "a1[1]: " << a1.get(1) << "\n";
    std::cout << "a2[1]: " << a2.get(1) << "\n";
    return 0;
}

#include <iostream>
#include <stdexcept>
#include <cstddef>

class Array {
private:
    std::size_t size;
    int* ptr;

public:
    explicit Array(int arraySize = 5)
        : size(arraySize > 0 ? static_cast<std::size_t>(arraySize)
                             : throw std::invalid_argument("Size must be > 0")),
          ptr(new int[size]) {
        for (std::size_t i = 0; i < size; ++i) ptr[i] = 0;
    }

    Array(const Array& right)
        : size(right.size), ptr(new int[right.size]) {
        for (std::size_t i = 0; i < size; ++i) ptr[i] = right.ptr[i];
    }

    ~Array() {
        delete[] ptr;
    }

    std::size_t getSize() const noexcept { return size; }

    // Overloaded assignment
    const Array& operator=(const Array& right) {
        if (&right != this) { // Avoid self-assignment
            if (size != right.size) {
                delete[] ptr;
                size = right.size;
                ptr = new int[size];
            }
            for (std::size_t i = 0; i < size; ++i) {
                ptr[i] = right.ptr[i];
            }
        }
        return *this;
    }

    // Equality
    bool operator==(const Array& right) const noexcept {
        if (size != right.size) return false;
        for (std::size_t i = 0; i < size; ++i) {
            if (ptr[i] != right.ptr[i]) return false;
        }
        return true;
    }

    // Inequality invokes ==
    bool operator!=(const Array& right) const noexcept {
        return !(*this == right);
    }

    // Subscript for non-const objects (modifiable lvalue)
    int& operator[](int subscript) {
        if (subscript < 0 || static_cast<std::size_t>(subscript) >= size) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr[subscript];
    }

    // Subscript for const objects (rvalue / read-only)
    int operator[](int subscript) const {
        if (subscript < 0 || static_cast<std::size_t>(subscript) >= size) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr[subscript];
    }
};

int main() {
    Array a1(3);
    Array a2(5);

    a1[0] = 10; a1[1] = 20; a1[2] = 30;
    std::cout << "a1 != a2: " << (a1 != a2 ? "true" : "false") << "\n";

    a2 = a1; // Resize a2 to 3 elements and deep-copy
    std::cout << "After assignment, a1 == a2: " << (a1 == a2 ? "true" : "false") << "\n";
    std::cout << "a2 size: " << a2.getSize() << ", a2[1]: " << a2[1] << "\n";

    try {
        a2[10] = 500; // Out of bounds
    } catch (const std::out_of_range& e) {
        std::cout << "Caught exception: " << e.what() << "\n";
    }

    return 0;
}
